import assert from 'node:assert/strict';
import {Router} from './src/http/router.ts';
import {orderRoutes} from './src/orders/routes/order-routes.ts';
import {InMemoryOrderStore} from './src/orders/integration/order-store.ts';
function setup(status='pending', owner='alice') {
 const orders=new InMemoryOrderStore([{id:'o1',customerId:owner,status,items:['sku']}]);
 const sessions={lookup:t=>t==='alice-token'?{id:'alice'}:undefined};
 return {orders,router:orderRoutes(new Router(),{orders,sessions})};
}
const auth={authorization:'Bearer alice-token'};
for (const [name,status,owner,headers,expected] of [
 ['R1 owner','pending','alice',auth,200],
 ['R2 absent','pending','alice',{},401],
 ['R2 invalid','pending','alice',{authorization:'Bearer invalid'},401],
 ['R3 other owner','pending','bob',auth,404],
 ['R4 shipped','shipped','alice',auth,'4xx'],
 ['R4 cancelled','cancelled','alice',auth,'4xx']]) {
 const {orders,router}=setup(status,owner); const before=orders.all();
 try {
 const res=router.handle({method:'POST',path:'/orders/o1/cancel',headers});
 if(expected==='4xx') assert.ok(res.status>=400&&res.status<500); else assert.equal(res.status,expected);
 if(expected===200) assert.equal(orders.get('o1').status,'cancelled'); else assert.deepEqual(orders.all(),before);
 console.log(name, 'PASS',res.status);
 } catch(e) {assert.deepEqual(orders.all(),before); console.log(name,'FAIL',e.name,e.message,'state unchanged');}
}
const {orders,router}=setup();
assert.equal(router.handle({method:'GET',path:'/orders/o1',headers:auth}).status,200);
assert.equal(router.handle({method:'GET',path:'/orders/o1',headers:{}}).status,401);
assert.equal(router.handle({method:'POST',path:'/orders',headers:auth,body:{items:['new']}}).status,201);
assert.equal(orders.all().length,2);
assert.equal(router.handle({method:'POST',path:'/orders',headers:auth,body:{items:[]}}).status,400);
assert.equal(router.handle({method:'POST',path:'/orders/missing/cancel',headers:auth}).status,404);
console.log('R5 existing GET/create validation + missing cancellation PASS');
